import {$,esc,money,time,state,onData,createTool,options,ranges,rangeFields,preview,exportCSV,activateInitial} from './workbench.js';
import {simulationCandidates,sampleHit,drawSample,trendPoints} from './tools-core.js';
createTool('simulator','洗练模拟','先看样本，再定目标。','使用真实观察组合演练锁定与目标筛选；不预测游戏洗练结果。',`<div class="notice"><span>ⓘ</span><div><strong>样本演练模式</strong> · 未取得官方洗练概率与消耗规则。每次等权抽取一条已观察完整组合，样本占比不是游戏成功率；不会改变真实商品。</div></div><section class="card tool-form"><div class="tool-grid"><label>谪星<select id="sim-skin"></select></label><label>起始真实组合（最多列300组）<select id="sim-base"></select></label><label>自填每次消耗<input id="sim-cost" type="number" min="0" step="0.01" placeholder="可不填"></label><label>消耗单位<input id="sim-unit" maxlength="12" placeholder="如：道具个数"></label></div><div id="sim-locks" class="tool-checks"></div><h3>目标数值范围</h3><div class="tool-slot-grid">${rangeFields('sim')}</div><p id="sim-candidates" class="subtle-note"></p><div class="tool-actions"><button id="sim-once" class="button">演练一次</button><button id="sim-many" class="button secondary">演练100次</button><button id="sim-reset" class="button secondary">重置记录</button></div><p id="sim-message" role="status"></p></section><section class="card tool-form"><h2>演练记录</h2><p id="sim-total">尚未演练</p><div id="sim-results" class="tool-chips"></div><p class="subtle-note">去重样本不代表市场分布，收藏与挂牌采样也会产生偏差。固定星格和解锁状态仅用于筛选样本，不代表游戏允许的锁定规则。</p></section>`,'✧');
let atlasSamples=[];function simSamples(){const all=new Map();for(const item of [...state.samples,...atlasSamples])all.set(JSON.stringify([item.skin,item.slots,item.unlocks]),item);return [...all.values()]}
let bases=[],draws=0,hits=0,spent=0,records=[];
function reset(){draws=hits=spent=0;records=[];$('#sim-total').textContent='尚未演练';$('#sim-results').replaceChildren()}
function base(){return bases.find(item=>item.id===$('#sim-base').value)}
function candidates(){const item=base();return item?simulationCandidates(simSamples(),item,Array.from({length:item.slots.length},(_,i)=>$('#sim-lock-'+i)?.checked??false)):[]}
function describe(){try{const list=candidates(),target=ranges('sim'),matched=list.filter(item=>sampleHit(item,target)).length;$('#sim-candidates').textContent=`可用完整组合 ${list.length} 组 · 满足目标 ${matched} 组${list.length?' · 样本占比 '+(matched/list.length*100).toFixed(1)+'%':''}（非游戏概率）`;const disabled=!base()?.slots.length||!list.length;$('#sim-once').disabled=$('#sim-many').disabled=disabled;$('#sim-message').textContent=state.catalog.find(item=>item.name===$("#sim-skin").value)?.slotNames?.length===0?'该谪星无星格，不支持数值演练。':!base()?'该谪星尚无真实组合样本，等待采集后再演练。':''}catch(error){$('#sim-message').textContent=error.message;$('#sim-once').disabled=$('#sim-many').disabled=true}}
function changeBase(){reset();const item=base();$('#sim-locks').innerHTML=(item?.slots??[]).map((value,i)=>`<label><input id="sim-lock-${i}" type="checkbox" ${item.unlocks?.[i]===0?'checked disabled':''}>固定第${i+1}格：${value}${item.unlocks?.[i]===0?'（未解锁）':''}</label>`).join('');$('#sim-locks').onchange=()=>{reset();describe()};describe()}
function changeSkin(){bases=simSamples().filter(item=>item.skin===$('#sim-skin').value).slice(0,300);options($('#sim-base'),bases.map(item=>({value:item.id,label:`${item.slots.join(' / ')||'无星格'} · ${item.holesCount??item.slots.length}孔 · ${item.id}`})));changeBase()}
function run(count){try{const list=candidates(),target=ranges('sim'),costText=$('#sim-cost').value,cost=costText===''?0:Number(costText);if(!Number.isFinite(cost)||cost<0||cost>1e9)throw Error('请输入有效的非负单次消耗');for(let i=0;i<count;i++){const item=drawSample(list),hit=sampleHit(item,target);draws++;hits+=Number(hit);spent+=cost;records.unshift({item,hit,draw:draws})}records=records.slice(0,20);$('#sim-total').textContent=`累计演练 ${draws} 次 · 命中目标 ${hits} 次${costText!==''?' · 按自填消耗累计 '+spent.toLocaleString('zh-CN',{maximumFractionDigits:2})+' '+($('#sim-unit').value||'单位'):''} · 仅保留最近20条`;$('#sim-results').innerHTML=records.map((record,i)=>`<button class="sample-record" data-record="${i}">#${record.draw} · ${esc(record.item.slots.join(' / '))} ${record.hit?'✓ 目标匹配':''}</button>`).join('');document.querySelectorAll('[data-record]').forEach(button=>button.onclick=()=>preview(records[Number(button.dataset.record)].item));$('#sim-message').textContent='抽取真实完整组合完成，可点击记录查看来源商品。'}catch(error){$('#sim-message').textContent=error.message}}
window.addEventListener('atlas-simulation-samples',event=>{atlasSamples=event.detail;changeSkin()});
$('#sim-skin').onchange=changeSkin;$('#sim-base').onchange=changeBase;$('#sim-once').onclick=()=>run(1);$('#sim-many').onclick=()=>run(100);$('#sim-reset').onclick=reset;for(const input of document.querySelectorAll('#simulator-view input'))input.addEventListener('input',()=>{reset();describe()});
window.addEventListener('simulate-skin',event=>{const skin=typeof event.detail==='string'?event.detail:event.detail?.skin;$('#sim-skin').value=skin;changeSkin()});
onData(()=>{const previous=base();options($('#sim-skin'),state.catalog);bases=simSamples().filter(item=>item.skin===$('#sim-skin').value).slice(0,300);options($('#sim-base'),bases.map(item=>({value:item.id,label:`${item.slots.join(' / ')||'无星格'} · ${item.holesCount??item.slots.length}孔 · ${item.id}`})));if(!previous||previous.id!==base()?.id||JSON.stringify([previous.slots,previous.unlocks])!==JSON.stringify([base()?.slots,base()?.unlocks]))changeBase();else describe()});

createTool('trends','条件趋势','把价格放回时间里。','按同款、孔数和数值条件比较历史挂牌底价。缺采和无匹配时保留空白。',`<section class="card tool-form"><div class="tool-grid"><label>主要谪星<select id="trend-skin"></select></label><label>对照谪星<select id="trend-second"></select></label><label>已解锁孔数<select id="trend-holes"><option value="">不限</option>${[0,1,2,3,4].map(n=>`<option value="${n}">${n}孔</option>`).join('')}</select></label><label>观察范围<select id="trend-days"><option value="1">24小时</option><option value="7" selected>7天</option><option value="30">30天</option></select></label></div><div class="tool-slot-grid">${rangeFields('trend')}</div><div class="tool-actions"><button id="trend-apply" class="button">更新趋势</button><button id="trend-reset" class="button secondary">清空附加搜索条件</button><button id="trend-export" class="button secondary">导出采样点</button><label><input id="trend-median" type="checkbox" checked>最低三件中位数</label></div><p id="trend-condition" class="subtle-note"></p><p id="trend-error" role="status"></p></section><section class="card tool-form"><div id="trend-stats" class="tool-grid"></div><div id="trend-chart" class="trend-chart" aria-label="真实采样趋势图"></div><div id="trend-hover" class="subtle-note" aria-live="polite"></div><p class="subtle-note">蓝色：主要谪星最低价；虚线：最低三件中位数；橙色：对照谪星最低价。观察间隔超过54分钟断线；缺采不补零。不代表成交价或全市场历史最低价。原始采样每3天清理一次，仅显示实际保留的数据，长区间可能不完整。</p></section>`,'↗');
let extra={},series=[],other=[];
function filters(){return {...extra,skin:$('#trend-skin').value,holes:$('#trend-holes').value,ranges:ranges('trend')}}
function renderTrend(){try{const filter=filters(),days=Number($('#trend-days').value),categories=new Map(state.catalog.map(c=>[c.name,c.category])),batches=state.data.batches.map(batch=>({...batch,items:batch.items.map(item=>({...item,category:categories.get(item.skin)}))}));series=trendPoints(batches,filter,days);other=$('#trend-second').value?trendPoints(batches,{...filter,skin:$('#trend-second').value},days):[];const valid=series.filter(p=>p.min!=null),first=valid[0],last=valid.at(-1),min=valid.length?Math.min(...valid.map(p=>p.min)):null;$('#trend-stats').innerHTML=`<div><small>最近有效样本底价</small><h2>${money(last?.min)}</h2><small>${time(last?.at)}</small></div><div><small>区间观察最低价</small><h2>${money(min)}</h2><small>${valid.length} 个有效点 / ${series.length} 次采样</small></div><div><small>区间首末变化</small><h2>${first&&last&&first!==last?((last.min-first.min)/first.min*100).toFixed(2)+'%':'—'}</h2><small>按实际首末有效观察时间计算</small></div>`;$('#trend-condition').textContent=Object.keys(extra).length?'已继承自定搜索的价格、收藏、解锁及商品范围条件；修改谪星/孔数/星格后其余条件仍保留。':'仅按上方谪星、孔数与星格条件筛选。';$('#trend-error').textContent='';chart()}catch(error){$('#trend-error').textContent=error.message}}
function chart(){const host=$('#trend-chart'),all=[...series,...other],valid=all.filter(p=>p.min!=null);if(!valid.length){host.innerHTML='<div class="empty">此时间范围没有匹配的真实采样记录。</div>';$('#trend-hover').textContent='';return}const width=900,height=310,left=80,right=20,top=20,bottom=50,start=Math.min(...all.map(p=>Date.parse(p.at))),end=Math.max(...all.map(p=>Date.parse(p.at))),values=valid.flatMap(p=>[p.min,...(p.median!=null?[p.median]:[])]),low=Math.min(...values),high=Math.max(...values),padding=Math.max((high-low)*.12,100),x=at=>left+(Date.parse(at)-start)/Math.max(1,end-start)*(width-left-right),y=value=>height-bottom-(value-low+padding)/(high-low+2*padding)*(height-top-bottom);
 const path=(points,key)=>{let previous=null;return points.map(point=>{if(point[key]==null){previous=null;return ''}const segment=`${previous&&Date.parse(point.at)-Date.parse(previous.at)<=54*60000?'L':'M'}${x(point.at).toFixed(2)},${y(point[key]).toFixed(2)}`;previous=point;return segment}).join(' ')};
 host.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc($('#trend-skin').value)}真实挂牌底价趋势">${Array.from({length:4},(_,i)=>{const price=low+(high-low)*i/3;return `<line x1="${left}" x2="${width-right}" y1="${y(price)}" y2="${y(price)}" stroke="#e7ebf0"/><text x="${left-8}" y="${y(price)+4}" text-anchor="end">${esc(money(price))}</text>`}).join('')}<path d="${path(series,'min')}" fill="none" stroke="#4979ed" stroke-width="2.5"/>${$('#trend-median').checked?`<path d="${path(series,'median')}" fill="none" stroke="#8799bc" stroke-width="2" stroke-dasharray="5 5"/>`:''}<path d="${path(other,'min')}" fill="none" stroke="#d78639" stroke-width="2.5"/>${series.map((point,i)=>point.min==null?'':`<circle tabindex="0" data-point="${i}" cx="${x(point.at)}" cy="${y(point.min)}" r="4" fill="#4979ed"><title>${esc(time(point.at)+' · '+money(point.min)+' · '+point.count+'件')}</title></circle>`).join('')}${other.filter(point=>point.min!=null).map(point=>`<circle cx="${x(point.at)}" cy="${y(point.min)}" r="3" fill="#d78639"><title>${esc(time(point.at)+' · '+money(point.min))}</title></circle>`).join('')}<text x="${left}" y="${height-15}">${esc(time(new Date(start).toISOString()))}</text><text x="${width-right}" y="${height-15}" text-anchor="end">${esc(time(new Date(end).toISOString()))}</text></svg>`;host.querySelectorAll('[data-point]').forEach(circle=>{const show=()=>{const p=series[Number(circle.dataset.point)];$('#trend-hover').textContent=`${time(p.at)} · 最低 ${money(p.min)} · 最低三件中位数 ${money(p.median)} · ${p.count}件匹配`};circle.onmouseenter=circle.onfocus=show});$('#trend-hover').textContent=`有效观察：${time(series.find(p=>p.min!=null)?.at)} 至 ${time(series.filter(p=>p.min!=null).at(-1)?.at)}`}
$('#trend-apply').onclick=renderTrend;$('#trend-days').onchange=$('#trend-median').onchange=renderTrend;$('#trend-reset').onclick=()=>{extra={};renderTrend()};$('#trend-export').onclick=()=>{renderTrend();exportCSV('谪星条件趋势.csv',[['序列','观察时间','最低挂牌价/元','最低三件中位数/元','匹配数','采样状态'],...[...series.map(p=>({...p,skin:$('#trend-skin').value})),...other.map(p=>({...p,skin:$('#trend-second').value}))].map(p=>[p.skin,p.at,p.min==null?'':p.min/100,p.median==null?'':p.median/100,p.count,p.coverage])])};
window.addEventListener('trend-condition',event=>{const {skin,holes,ranges:slotRanges,...rest}=event.detail;extra=rest;$('#trend-skin').value=skin??'';$('#trend-holes').value=holes??'';for(let i=0;i<4;i++){ $('#trend-min-'+i).value=slotRanges?.[i]?.min??'';$('#trend-max-'+i).value=slotRanges?.[i]?.max??''}renderTrend()});
onData(()=>{options($('#trend-skin'),state.catalog,'全部谪星');options($('#trend-second'),state.catalog,'不对照');renderTrend()});activateInitial();
